import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.DynamicObject;
import net.runelite.api.GameObject;
import net.runelite.api.Renderable;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarPlayerID;

class CannonActivity
{
	private GameObject observed;
	private int stoppedSince = -1;

	boolean isInactive(Client client)
	{
		GameObject cannon = findCannon(client);
		if (cannon == null)
		{
			clear();
			return false;
		}
		Renderable renderable = cannon.getRenderable();
		Animation animation = renderable instanceof DynamicObject ? ((DynamicObject) renderable).getAnimation() : null;
		if (renderable == null || (animation != null && animation.getId() != AnimationID.CANNON_LEAGUE03_IDLE))
		{
			clear();
			return false;
		}
		int tick = client.getTickCount();
		if (observed != cannon || stoppedSince < 0 || tick < stoppedSince)
		{
			observed = cannon;
			stoppedSince = tick;
		}
		// Allow the short gap between successive turning animations.
		return tick - stoppedSince >= 2;
	}

	private GameObject findCannon(Client client)
	{
		WorldView world = client.getTopLevelWorldView();
		if (world == null) { return null; }
		WorldPoint position = WorldPoint.fromCoord(client.getVarpValue(VarPlayerID.OWNEDMCANNON));
		if (position.getPlane() != world.getPlane()) { return null; }
		int x = position.getX() - world.getBaseX();
		int y = position.getY() - world.getBaseY();
		Tile[][] tiles = world.getScene().getTiles()[position.getPlane()];
		if (x < 0 || x >= tiles.length || y < 0 || y >= tiles[x].length) { return null; }
		Tile tile = tiles[x][y];
		if (tile == null) { return null; }
		for (GameObject object : tile.getGameObjects())
		{
			if (object != null && (object.getId() == ObjectID.DWARF_MULTICANNON1
				|| object.getId() == ObjectID.LEAGUE03_MULTICANNON_ACTIVE)
				&& object.getSceneMinLocation().getX() == x && object.getSceneMinLocation().getY() == y)
			{
				return object;
			}
		}
		return null;
	}

	void clear()
	{
		observed = null;
		stoppedSince = -1;
	}
}

package com.altingtoolbox;

import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;

final class GroundDrops
{
	private final Map<TileItem, Tile> items = new IdentityHashMap<>();
	private Set<Integer> ids = Set.of();

	void configure(String text)
	{
		Set<Integer> parsed = new HashSet<>();
		for (String token : text.split("[,;\\s]+"))
		{
			try
			{
				int id = Integer.parseInt(token);
				if (id > 0) { parsed.add(id); }
			}
			catch (NumberFormatException ignored) { }
		}
		ids = parsed;
		clear();
	}

	boolean isConfigured() { return !ids.isEmpty(); }

	boolean add(TileItem item, Tile tile)
	{
		if (!ids.contains(item.getId())) { return false; }
		items.put(item, tile);
		return true;
	}

	boolean remove(TileItem item) { return items.remove(item) != null; }

	void clear() { items.clear(); }

	TileItem nearest(WorldPoint player, int range, boolean ownOnly)
	{
		TileItem nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (Map.Entry<TileItem, Tile> entry : items.entrySet())
		{
			TileItem item = entry.getKey();
			int owner = item.getOwnership();
			boolean mine = owner == TileItem.OWNERSHIP_SELF || owner == TileItem.OWNERSHIP_GROUP;
			if (item.getQuantity() <= 0 || (ownOnly && !mine) || (item.isPrivate() && !mine)) { continue; }
			int distance = player.distanceTo(entry.getValue().getWorldLocation());
			if (distance <= range && (distance < nearestDistance
				|| (distance == nearestDistance && nearest != null && item.getId() < nearest.getId())))
			{
				nearest = item;
				nearestDistance = distance;
			}
		}
		return nearest;
	}
}

package com.altingtoolbox;

final class PoisonProtection
{
	private static final int POISON_TICKS = 30;
	private int value;
	private int nextTick = -1;

	void update(int newValue, int tick)
	{
		if (newValue != value || nextTick < 0)
		{
			if (newValue == 0) { nextTick = -1; }
			else if (nextTick <= tick) { nextTick = tick + POISON_TICKS; }
			value = newValue;
		}
	}

	boolean isProtected() { return value < 0; }

	String status(int tick)
	{
		if (!isProtected()) { return value > 0 ? "Poison: affected" : "Poison: unprotected"; }
		boolean venomProtection = value < -38;
		int remainingSteps = venomProtection ? -(value + 38) : -value;
		int ticks = Math.max(0, nextTick - tick + (remainingSteps - 1) * POISON_TICKS);
		int seconds = (ticks * 3 + 4) / 5;
		return (venomProtection ? "Anti-venom: " : "Anti-poison: ")
			+ seconds / 60 + ":" + String.format("%02d", seconds % 60);
	}

	void clear()
	{
		value = 0;
		nextTick = -1;
	}
}

package com.altingtoolbox;

import java.awt.Color;
import java.util.List;

final class ToolboxDisplay
{
	static final ToolboxDisplay HIDDEN = new ToolboxDisplay(false, List.of(), List.of());
	final boolean visible;
	final List<Alert> alerts;
	final List<String> status;
	final long undimUntilNanos;

	ToolboxDisplay(boolean visible, List<Alert> alerts, List<String> status)
	{
		this(visible, alerts, status, 0);
	}

	ToolboxDisplay(boolean visible, List<Alert> alerts, List<String> status, long undimUntilNanos)
	{
		this.visible = visible;
		this.alerts = List.copyOf(alerts);
		this.status = List.copyOf(status);
		this.undimUntilNanos = undimUntilNanos;
	}

	Alert activeAlert(long elapsedMillis, int rotationSeconds)
	{
		if (alerts.isEmpty()) { return null; }
		int index = (int) ((Math.max(0, elapsedMillis) / (Math.max(1, rotationSeconds) * 1000L)) % alerts.size());
		return alerts.get(index);
	}

	boolean hasSameAlerts(ToolboxDisplay other)
	{
		if (alerts.size() != other.alerts.size()) { return false; }
		for (int i = 0; i < alerts.size(); i++)
		{
			if (!alerts.get(i).message.equals(other.alerts.get(i).message)) { return false; }
		}
		return true;
	}

	static String cannonText(String prefix, int ammo)
	{
		String label = prefix.trim();
		return label.isEmpty() ? Integer.toString(ammo) : label + " " + ammo;
	}

	static final class Alert
	{
		final String message;
		final Color color;
		final AltingToolboxConfig.AlertStyle style;

		Alert(String message, Color color, AltingToolboxConfig.AlertStyle style)
		{
			this.message = message;
			this.color = color;
			this.style = style;
		}
	}
}

