		assertFalse(plugin.getDisplay().visible);
		listener.getValue().hotkeyPressed();
		assertEquals(List.of("Restore prayer"), messages());
	}

	@Test
	public void shutdownRemovesOverlaysAndSuppressesQueuedSound()
	{
		spawnCoins();
		ArgumentCaptor<Runnable> sound = ArgumentCaptor.forClass(Runnable.class);
		verify(executor).submit(sound.capture());
		plugin.shutDown();
		sound.getValue().run();
		assertFalse(plugin.getDisplay().visible);
		verify(overlayManager).remove(overlay);
		verify(overlayManager).remove(textOverlay);
		verifyNoInteractions(audioPlayer);
	}

	private ItemSpawned spawnCoins()
	{
		when(config.dropIds()).thenReturn("995");
		ConfigChanged configChange = new ConfigChanged();
		configChange.setGroup(AltingToolboxConfig.GROUP);
		configChange.setKey("dropIds");
		plugin.onConfigChanged(configChange);
		TileItem item = mock(TileItem.class);
		when(item.getId()).thenReturn(995);
		when(item.getQuantity()).thenReturn(10);
		when(item.getOwnership()).thenReturn(TileItem.OWNERSHIP_SELF);
		Tile tile = mock(Tile.class);
		when(tile.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
		ItemComposition definition = mock(ItemComposition.class);
		when(definition.getName()).thenReturn("Coins");
		when(itemManager.getItemComposition(995)).thenReturn(definition);
		ItemSpawned event = new ItemSpawned(tile, item);
		plugin.onItemSpawned(event);
		return event;
	}

	private void tick() { plugin.onGameTick(new GameTick()); }

	private List<String> messages()
	{
		return plugin.getDisplay().alerts.stream().map(alert -> alert.message).collect(Collectors.toList());
	}
}

package com.altingtoolbox;

import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.DynamicObject;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.Point;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarPlayerID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CannonActivityTest
{
	private final Client client = mock(Client.class);
	private final WorldView world = mock(WorldView.class);
	private final GameObject cannon = mock(GameObject.class);
	private final DynamicObject rotating = mock(DynamicObject.class);
	private final Tile tile = mock(Tile.class);
	private final CannonActivity activity = new CannonActivity();

	@Before
	public void setUp()
	{
		placeCannon(client, world, tile, cannon, rotating);
	}

	static void placeCannon(Client client, WorldView world, Tile tile, GameObject cannon, DynamicObject renderable)
	{
		Scene scene = mock(Scene.class);
		when(client.getTopLevelWorldView()).thenReturn(world);
		when(client.getVarpValue(VarPlayerID.OWNEDMCANNON)).thenReturn((3200 << 14) | 3200);
		when(world.getBaseX()).thenReturn(3200);
		when(world.getBaseY()).thenReturn(3200);
		when(world.getScene()).thenReturn(scene);
		Tile[][][] tiles = new Tile[4][2][2];
		tiles[0][0][0] = tile;
		when(scene.getTiles()).thenReturn(tiles);
		when(tile.getGameObjects()).thenReturn(new GameObject[]{cannon});
		when(cannon.getId()).thenReturn(ObjectID.DWARF_MULTICANNON1);
		when(cannon.getSceneMinLocation()).thenReturn(new Point(0, 0));
		when(cannon.getRenderable()).thenReturn(renderable);
	}

	@Test
	public void loadedStationaryCannonAlertsAndStartingRotationClearsIt()
	{
		when(cannon.getRenderable()).thenReturn(mock(Model.class));
		assertFalse(activity.isInactive(client));
		when(client.getTickCount()).thenReturn(2);
		assertTrue(activity.isInactive(client));
		when(cannon.getRenderable()).thenReturn(rotating);
		animate(AnimationID.MCANNON_N_TURN);
		assertFalse(activity.isInactive(client));
	}

	@Test
	public void everyTurnWithoutFiringStaysActiveRegardlessOfAmmo()
	{
		when(client.getVarpValue(VarPlayerID.ROCKTHROWER)).thenReturn(30);
		for (int id = AnimationID.MCANNON_N_TURN; id <= AnimationID.MCANNON_NW_TURN; id++)
		{
			animate(id);
			when(client.getTickCount()).thenReturn(id * 100);
			assertFalse(activity.isInactive(client));
		}
	}

	@Test
	public void temporaryAnimationGapDoesNotAlertButStoppingDoes()
	{
		animate(AnimationID.MCANNON_N_FIRE);
		assertFalse(activity.isInactive(client));
		when(rotating.getAnimation()).thenReturn(null);
		when(client.getTickCount()).thenReturn(1);
		assertFalse(activity.isInactive(client));
		when(client.getTickCount()).thenReturn(2);
		assertFalse(activity.isInactive(client));
		animate(AnimationID.MCANNON_NE_TURN);
		assertFalse(activity.isInactive(client));
		when(rotating.getAnimation()).thenReturn(null);
		assertFalse(activity.isInactive(client));
		when(client.getTickCount()).thenReturn(4);
		assertTrue(activity.isInactive(client));
	}

	@Test
	public void ornamentedIdleCannonAlertsButAimingDoesNot()
	{
		when(cannon.getId()).thenReturn(ObjectID.LEAGUE03_MULTICANNON_ACTIVE);
		animate(AnimationID.CANNON_LEAGUE03_IDLE);
		assertFalse(activity.isInactive(client));
		when(client.getTickCount()).thenReturn(2);
		assertTrue(activity.isInactive(client));
		animate(AnimationID.CANNON_LEAGUE03_AIM_N);
		assertFalse(activity.isInactive(client));
	}

	@Test
	public void missingOrOtherPlayersCannonsDoNotAlert()
	{
		assertFalse(activity.isInactive(client));
		when(client.getTickCount()).thenReturn(2);
		when(cannon.getSceneMinLocation()).thenReturn(new Point(1, 0));
		assertFalse(activity.isInactive(client));
		when(tile.getGameObjects()).thenReturn(new GameObject[0]);
		assertFalse(activity.isInactive(client));
		when(world.getBaseX()).thenReturn(4000);
		assertFalse(activity.isInactive(client));
		when(world.getBaseX()).thenReturn(3200);
		when(world.getPlane()).thenReturn(1);
		assertFalse(activity.isInactive(client));
	}

	private void animate(int id)
	{
		Animation animation = mock(Animation.class);
		when(animation.getId()).thenReturn(id);
		when(rotating.getAnimation()).thenReturn(animation);
	}
}

package com.altingtoolbox;

import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class GroundDropsTest
{
	private final GroundDrops drops = new GroundDrops();
	private final WorldPoint player = new WorldPoint(3200, 3200, 0);

	@Test
	public void tracksEachStackUntilTheLastOneLeaves()
	{
		drops.configure("995, 4151");
		Tile tile = tileAt(player);
		TileItem first = item(995);
		TileItem second = item(995);
		drops.add(first, tile);
		drops.add(second, tile);
		assertNotNull(drops.nearest(player, 20, false));
		drops.remove(first);
		assertSame(second, drops.nearest(player, 20, false));
		drops.remove(second);
		assertNull(drops.nearest(player, 20, false));
	}

	@Test
	public void respectsRangeAndPlaneAsThePlayerMoves()
	{
		drops.configure("995");
		TileItem item = item(995);
		drops.add(item, tileAt(new WorldPoint(3220, 3200, 0)));
		assertSame(item, drops.nearest(player, 20, false));
		assertNull(drops.nearest(player, 19, false));
		assertNull(drops.nearest(new WorldPoint(3200, 3200, 1), 64, false));
		assertSame(item, drops.nearest(new WorldPoint(3210, 3200, 0), 10, false));
	}

	@Test
	public void privateLootBecomesEligibleWhenItIsPublic()
	{
		drops.configure("995");
		TileItem item = item(995);
		when(item.getOwnership()).thenReturn(TileItem.OWNERSHIP_OTHER);
		when(item.isPrivate()).thenReturn(true);
		drops.add(item, tileAt(player));
		assertNull(drops.nearest(player, 20, false));
		when(item.isPrivate()).thenReturn(false);
		assertSame(item, drops.nearest(player, 20, false));
		assertNull(drops.nearest(player, 20, true));
		when(item.getOwnership()).thenReturn(TileItem.OWNERSHIP_GROUP);
		assertSame(item, drops.nearest(player, 20, true));
	}

	@Test
	public void configurationAcceptsSeparatorsAndIgnoresInvalidIds()
	{
		drops.configure("995,\n4151; 995 invalid -1 9999999999999999999");
		assertTrue(drops.add(item(995), tileAt(player)));
		assertTrue(drops.add(item(4151), tileAt(player)));
		assertFalse(drops.add(item(526), tileAt(player)));
		drops.configure("");
		assertFalse(drops.isConfigured());
		assertNull(drops.nearest(player, 20, false));
	}

	@Test
	public void aPartialPickupDoesNotClearTheDrop()
	{
		drops.configure("995");
		TileItem item = item(995);
		when(item.getQuantity()).thenReturn(50);
		drops.add(item, tileAt(player));
		when(item.getQuantity()).thenReturn(25);
		assertSame(item, drops.nearest(player, 20, false));
		when(item.getQuantity()).thenReturn(0);
		assertNull(drops.nearest(player, 20, false));
	}

	private TileItem item(int id)
	{
		TileItem item = mock(TileItem.class);
		when(item.getId()).thenReturn(id);
		when(item.getQuantity()).thenReturn(1);
		when(item.getOwnership()).thenReturn(TileItem.OWNERSHIP_SELF);
		return item;
	}

	private Tile tileAt(WorldPoint point)
	{
		Tile tile = mock(Tile.class);
		when(tile.getWorldLocation()).thenReturn(point);
		return tile;
	}
}

package com.altingtoolbox;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayLayer;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class OverlayRenderingTest
{
	private final Client client = mock(Client.class);
	private final AltingToolboxPlugin plugin = mock(AltingToolboxPlugin.class);
	private final AltingToolboxConfig config = new AltingToolboxConfig() { };
	private final AltingToolboxOverlay overlay = new AltingToolboxOverlay(client, plugin, config);

	@Before
	public void setUp()
	{
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getCanvasWidth()).thenReturn(100);
		when(client.getCanvasHeight()).thenReturn(100);
	}

	@Test
	public void idleScreenIsDimmed()
	{
		when(plugin.getDisplay()).thenReturn(new ToolboxDisplay(true, List.of(), List.of()));
		Color pixel = render();
		assertEquals(55, pixel.getRed());
		assertEquals(55, pixel.getGreen());
		assertEquals(55, pixel.getBlue());
	}

	@Test
	public void pickupDelayKeepsTheScreenClearUntilItsDeadline()
	{
		when(plugin.getDisplay()).thenReturn(new ToolboxDisplay(true, List.of(), List.of(), System.nanoTime() + 3_000_000_000L));
		assertEquals(Color.WHITE, render());
		when(plugin.getDisplay()).thenReturn(new ToolboxDisplay(true, List.of(), List.of(), System.nanoTime() - 1));
		assertEquals(55, render().getRed());
	}

	@Test
	public void otherAlertsStillRenderDuringPickupDelay()
	{
		ToolboxDisplay.Alert alert = new ToolboxDisplay.Alert("Restore health", Color.RED, AltingToolboxConfig.AlertStyle.SOLID);
		when(plugin.getDisplay()).thenReturn(new ToolboxDisplay(true, List.of(alert), List.of(), System.nanoTime() + 3_000_000_000L));
		Color pixel = render();
		assertEquals(255, pixel.getRed());
		assertEquals(155, pixel.getGreen());
	}

	@Test
	public void solidAlertReplacesTheDim()
	{
		setAlert(AltingToolboxConfig.AlertStyle.SOLID);
		when(plugin.elapsedMillis()).thenReturn(1000L);
		Color pixel = render();
		assertEquals(255, pixel.getRed());
		assertEquals(155, pixel.getGreen());
	}

	@Test
	public void flashOffPhaseLeavesTheGameClear()
	{
		setAlert(AltingToolboxConfig.AlertStyle.FLASH);
		when(plugin.elapsedMillis()).thenReturn(1000L);
		assertEquals(Color.WHITE, render());
		when(plugin.elapsedMillis()).thenReturn(1200L);
		assertEquals(155, render().getGreen());
	}

	@Test
	public void textStaysWhiteAboveDimmingAndSolidAlerts()
	{
		when(client.getCanvasWidth()).thenReturn(800);
		when(client.getCanvasHeight()).thenReturn(600);
		AltingToolboxTextOverlay text = new AltingToolboxTextOverlay(client, plugin, config);
		ToolboxDisplay.Alert alert = new ToolboxDisplay.Alert("Restore health", Color.RED, AltingToolboxConfig.AlertStyle.SOLID);
		for (List<ToolboxDisplay.Alert> alerts : List.of(List.<ToolboxDisplay.Alert>of(), List.of(alert)))
		{
			when(plugin.getDisplay()).thenReturn(new ToolboxDisplay(true, alerts, List.of("30")));
			BufferedImage image = new BufferedImage(800, 600, BufferedImage.TYPE_INT_RGB);
			for (OverlayLayer layer : OverlayLayer.values())
			{
				Graphics2D graphics = image.createGraphics();
				try
				{
					if (layer == text.getLayer()) { text.render(graphics); }
					if (layer == overlay.getLayer()) { overlay.render(graphics); }
				}
				finally { graphics.dispose(); }
			}
			boolean hasWhiteText = false;
			for (int y = 270; y < 330; y++)
			{
				for (int x = 280; x < 520; x++)
				{
					hasWhiteText |= image.getRGB(x, y) == Color.WHITE.getRGB();
				}
			}
			assertTrue("Text should remain white above the screen tint", hasWhiteText);
			text.getBounds().setLocation(0, 0);
		}
	}

	@Test
	public void loginAndPausedStatesNeverDim()
	{
		when(plugin.getDisplay()).thenReturn(ToolboxDisplay.HIDDEN);
		assertEquals(Color.WHITE, render());
		when(plugin.getDisplay()).thenReturn(new ToolboxDisplay(true, List.of(), List.of()));
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		assertEquals(Color.WHITE, render());
	}

	private void setAlert(AltingToolboxConfig.AlertStyle style)
	{
		ToolboxDisplay.Alert alert = new ToolboxDisplay.Alert("Drink anti-poison", Color.RED, style);
		when(plugin.getDisplay()).thenReturn(new ToolboxDisplay(true, List.of(alert), List.of()));
	}

	private Color render()
	{
		BufferedImage image = new BufferedImage(100, 100, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setColor(Color.WHITE);
			graphics.fillRect(0, 0, 100, 100);
			overlay.render(graphics);
			return new Color(image.getRGB(50, 50));
		}
		finally { graphics.dispose(); }
	}
}

package com.altingtoolbox;

import org.junit.Test;
import static org.junit.Assert.*;

public class PoisonProtectionTest
{
	@Test
	public void onlyImmunityClearsTheWarning()
	{
		PoisonProtection protection = new PoisonProtection();
		for (int value : new int[] {0, 5, 1000000})
		{
			protection.update(value, 10);
			assertFalse(protection.isProtected());
		}
		protection.update(-1, 10);
		assertTrue(protection.isProtected());
		protection.update(0, 40);
		assertFalse(protection.isProtected());
	}

	@Test
	public void countdownKeepsTheObservedPoisonTickPhase()
	{
		PoisonProtection protection = new PoisonProtection();
		protection.update(-2, 10);
		assertEquals("Anti-poison: 0:36", protection.status(10));
		assertEquals("Anti-poison: 0:30", protection.status(20));
		protection.update(-1, 40);
		assertEquals("Anti-poison: 0:18", protection.status(40));
	}

	@Test
	public void antivenomTransitionsToAntipoisonWithoutAnAlert()
	{
		PoisonProtection protection = new PoisonProtection();
		protection.update(-39, 10);
		assertEquals("Anti-venom: 0:18", protection.status(10));
		protection.update(-38, 40);
		assertTrue(protection.isProtected());
		assertEquals("Anti-poison: 11:24", protection.status(40));
		protection.clear();
		assertFalse(protection.isProtected());
	}
}

package com.altingtoolbox;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.Client;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TextOverlayTest
{
	private final Client client = mock(Client.class);
	private final AltingToolboxPlugin plugin = mock(AltingToolboxPlugin.class);
	private final AltingToolboxTextOverlay overlay = new AltingToolboxTextOverlay(client, plugin, new AltingToolboxConfig() { });

	@Test
	public void differentMessagesStayAtTheCanvasCenter()
	{
		assertCentered(List.of("30"), 800, 600, 400, 300);
		assertCentered(List.of("Drink anti-poison"), 800, 600, 400, 300);
		assertCentered(List.of("Pick up a very long item name"), 800, 600, 400, 300);
		assertCentered(List.of("30", "Prayer: 99", "Strength: 118"), 800, 600, 400, 300);
	}

	@Test
	public void defaultCenterFollowsCanvasResize()
	{
		assertCentered(List.of("30"), 800, 600, 400, 300);
		assertCentered(List.of("30"), 1000, 700, 500, 350);
	}

	@Test
	public void draggedMessagesKeepTheirMidpoint()
	{
		overlay.setPreferredLocation(new Point(100, 80));
		overlay.getBounds().setLocation(100, 80);
		assertCentered(List.of("30"), 800, 600, 220, 110);
		assertCentered(List.of("Drink anti-poison"), 800, 600, 220, 110);
	}

	private void assertCentered(List<String> lines, int width, int height, int centerX, int centerY)
	{
		when(client.getCanvasWidth()).thenReturn(width);
		when(client.getCanvasHeight()).thenReturn(height);
		when(plugin.getDisplay()).thenReturn(new ToolboxDisplay(true, List.of(), lines));
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.translate(overlay.getBounds().x, overlay.getBounds().y);
			Dimension size = overlay.render(graphics);
			overlay.getBounds().setSize(size);
			assertEquals(centerX, overlay.getBounds().getCenterX(), 0.5);
			assertEquals(centerY, overlay.getBounds().getCenterY(), 0.5);
			int left = width, right = 0, top = height, bottom = 0;
			for (int y = 0; y < height; y++)
			{
				for (int x = 0; x < width; x++)
				{
					if ((image.getRGB(x, y) >>> 24) == 0) { continue; }
					left = Math.min(left, x);
					right = Math.max(right, x);
					top = Math.min(top, y);
					bottom = Math.max(bottom, y);
				}
			}
			assertTrue(left < right);
			assertEquals(centerX, (left + right) / 2.0, 3);
			assertEquals(centerY, (top + bottom) / 2.0, 6);
		}
		finally { graphics.dispose(); }
	}
}

